package net.civeira.phylax.features.access.trustedclient.application.visibility;

import java.util.function.Consumer;
import java.util.function.UnaryOperator;

import lombok.Getter;
import lombok.NonNull;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.common.security.InvocationSource;
import net.civeira.phylax.common.security.OperationContext;

@Getter
public class TrustedClientVisibilityCheck {

  /**
   * @autogenerated VisibilityCheckGenerator
   */
  @NonNull
  private final OperationContext context;

  /**
   * @autogenerated VisibilityCheckGenerator
   */
  @NonNull
  private TrustedClientVisibilityFilter filter;

  /**
   * @autogenerated VisibilityCheckGenerator
   * @param context
   * @param filter
   */
  public TrustedClientVisibilityCheck(final OperationContext context,
      final TrustedClientVisibilityFilter filter) {
    this.context = context;
    this.filter = filter;
  }

  /**
   * @autogenerated VisibilityCheckGenerator
   * @return
   */
  public Actor getActor() {
    return this.context.getActor();
  }

  /**
   * @autogenerated VisibilityCheckGenerator
   * @return
   */
  public InvocationSource getSource() {
    return this.context.getSource();
  }

  /**
   * @autogenerated VisibilityCheckGenerator
   * @param mapper
   */
  public void map(UnaryOperator<TrustedClientVisibilityFilter> mapper) {
    filter = mapper.apply(filter);
  }

  /**
   * @autogenerated VisibilityCheckGenerator
   * @param mapper
   */
  public void peek(Consumer<TrustedClientVisibilityFilter> mapper) {
    mapper.accept(filter);
  }
}
